         },
         {
           question: "What is the best way to introduce a new cat?",
           answer:
             "Use a slow introduction: start with separate spaces, swap scents, allow brief supervised visual contact, and gradually increase time together. Rushing the process can make cats feel unsafe."
         }
       ];

       function Header() {
         return `
           <header class="page-shell">
             <nav aria-label="Primary navigation">
               <ul>
                 <li><a href="#faq">FAQ</a></li>
                 <li><a href="#care-note">Care note</a></li>
               </ul>
             </nav>
           </header>
         `;
       }

       function Hero() {
         return `
           <section class="hero" aria-labelledby="page-title">
             <div>
               <p class="eyebrow">Cat care basics</p>
               <h1 id="page-title">Curious Cat FAQ</h1>
               <p>
                 Quick answers for common cat questions, from feeding routines to
                 play, enrichment, and helping a new feline friend feel at home.
               </p>
             </div>
             <aside class="hero-card" id="care-note" aria-label="Cat care note">
               <div class="cat-mark" aria-hidden="true">cat</div>
               <strong>Small habits, calmer cats.</strong>
               <p>Consistent meals, clean litter, safe hiding spots, and daily play all support feline wellbeing.</p>
             </aside>
           </section>
         `;
       }

       function FAQItem(item, index) {
         const buttonId = `faq-button-${index}`;
         const detailsId = `faq-details-${index}`;

         return `
           <div class="example">
             <h3>
               <button
                 class="question-button"
                 type="button"
                 id="${buttonId}"
                 aria-expanded="false"
                 aria-controls="${detailsId}"
               >
                 <span>${item.question}</span>
                 <span class="icon" aria-hidden="true">+</span>
               </button>
             </h3>
             <div
               class="details"
               id="${detailsId}"
               role="region"
               aria-labelledby="${buttonId}"
               hidden
             >
               <p>${item.answer}</p>
             </div>
           </div>
         `;
       }

       function FAQSection(items) {
         return `
           <section class="faq-panel" id="faq" aria-labelledby="faq-heading">
             <h2 class="section-heading" id="faq-heading">Frequently asked questions</h2>
             <div class="faq-list">
               ${items.map(FAQItem).join("")}
             </div>
           </section>
         `;
       }

       function App() {
         return `
           ${Header()}
           <main class="page-shell" id="main-content">
             ${Hero()}
             ${FAQSection(faqs)}
           </main>
           <footer class="page-shell">
             <p>For medical concerns, contact a licensed veterinarian.</p>
           </footer>
         `;
       }

       function wireDisclosureButtons() {
         document.querySelectorAll(".question-button").forEach((button) => {
           button.addEventListener("click", () => {
             const details = document.getElementById(button.getAttribute("aria-controls"));
             const isExpanded = button.getAttribute("aria-expanded") === "true";
             const icon = button.querySelector(".icon");

             button.setAttribute("aria-expanded", String(!isExpanded));
             details.hidden = isExpanded;
             icon.textContent = isExpanded ? "+" : "-";
           });
         });
       }

       document.getElementById("app").innerHTML = App();
       wireDisclosureButtons();
     </script>
